202	// Proxy returns a Proxy middleware.
203	//
204	// Proxy middleware forwards the request to upstream server using a configured load balancing technique.
205	func Proxy(balancer ProxyBalancer) echo.MiddlewareFunc {
206		c := DefaultProxyConfig
207		c.Balancer = balancer
208		return ProxyWithConfig(c)
209	}
