211	// ProxyWithConfig returns a Proxy middleware with config.
212	// See: `Proxy()`
213	func ProxyWithConfig(config ProxyConfig) echo.MiddlewareFunc {
214		// Defaults
215		if config.Skipper == nil {
216			config.Skipper = DefaultProxyConfig.Skipper
217		}
218		if config.Balancer == nil {
219			panic("echo: proxy middleware requires balancer")
220		}
221	
222		if config.Rewrite != nil {
223			if config.RegexRewrite == nil {
224				config.RegexRewrite = make(map[*regexp.Regexp]string)
225			}
226			for k, v := range rewriteRulesRegex(config.Rewrite) {
227				config.RegexRewrite[k] = v
228			}
229		}
230	
231		return func(next echo.HandlerFunc) echo.HandlerFunc {
232			return func(c echo.Context) (err error) {
233				if config.Skipper(c) {
234					return next(c)
235				}
236	
237				req := c.Request()
238				res := c.Response()
239				tgt := config.Balancer.Next(c)
240				if tgt == nil {
241					return echo.ErrServiceUnavailable
242				}
243				c.Set(config.ContextKey, tgt)
244	
245				// Set rewrite path and raw path
246				rewritePath(config.RegexRewrite, req)
247	
248				// Fix header
249				// Basically it's not good practice to unconditionally pass incoming x-real-ip header to upstream.
250				// However, for backward compatibility, legacy behavior is preserved unless you configure Echo#IPExtractor.
251				if req.Header.Get(echo.HeaderXRealIP) == "" || c.Echo().IPExtractor != nil {
252					req.Header.Set(echo.HeaderXRealIP, c.RealIP())
253				}
254				if req.Header.Get(echo.HeaderXForwardedProto) == "" {
255					req.Header.Set(echo.HeaderXForwardedProto, c.Scheme())
256				}
257				if c.IsWebSocket() && req.Header.Get(echo.HeaderXForwardedFor) == "" { // For HTTP, it is automatically set by Go HTTP reverse proxy.
258					req.Header.Set(echo.HeaderXForwardedFor, c.RealIP())
259				}
260	
261				// Proxy
262				switch {
263				case c.IsWebSocket():
264					proxyRaw(tgt, c).ServeHTTP(res, req)
265				case req.Header.Get(echo.HeaderAccept) == "text/event-stream":
266				default:
267					proxyHTTP(tgt, c, config).ServeHTTP(res, req)
268				}
269				if e, ok := c.Get("_error").(error); ok {
270					err = e
271				}
272	
273				return
274			}
275		}
276	}

