package middleware

import (
	"net/http"
	"net/http/httptest"
	"testing"

	"github.com/labstack/echo/v4"
)

// TestProxyBalancerWithNoTargets verifies that a proxy balancer with zero
// targets does not panic and results in a non-2xx error response.
func TestProxyBalancerWithNoTargets(t *testing.T) {
	cases := []struct {
		name     string
		balancer ProxyBalancer
	}{
		{"roundRobinEmptySlice", NewRoundRobinBalancer([]*ProxyTarget{})},
		{"roundRobinNil", NewRoundRobinBalancer(nil)},
		{"randomEmptySlice", NewRandomBalancer([]*ProxyTarget{})},
		{"randomNil", NewRandomBalancer(nil)},
	}

	for _, tc := range cases {
		tc := tc
		t.Run(tc.name, func(t *testing.T) {
			// (2a) Next on a zero-target balancer must return nil (no panic).
			e := echo.New()
			req := httptest.NewRequest(http.MethodGet, "/", nil)
			rec := httptest.NewRecorder()
			c := e.NewContext(req, rec)
			if tgt := tc.balancer.Next(c); tgt != nil {
				t.Fatalf("balancer.Next with zero targets = %v, want nil", tgt)
			}

			// (2b) Serving a request through the proxy middleware must not panic
			// and must produce a non-2xx error status code.
			e2 := echo.New()
			e2.Use(Proxy(tc.balancer))
			e2.GET("/", func(c echo.Context) error {
				return c.String(http.StatusOK, "should not be reached")
			})

			req2 := httptest.NewRequest(http.MethodGet, "/", nil)
			rec2 := httptest.NewRecorder()

			panicked := false
			func() {
				defer func() {
					if r := recover(); r != nil {
						panicked = true
						t.Errorf("panic while serving request with zero-target balancer: %v", r)
					}
				}()
				e2.ServeHTTP(rec2, req2)
			}()

			if panicked {
				return
			}
			t.Logf("balancer=%s status=%d body=%q", tc.name, rec2.Code, rec2.Body.String())
			if rec2.Code >= 200 && rec2.Code < 300 {
				t.Errorf("status = %d, want non-2xx error code", rec2.Code)
			}
			if rec2.Code != http.StatusServiceUnavailable {
				t.Errorf("status = %d, want %d", rec2.Code, http.StatusServiceUnavailable)
			}
		})
	}
}
