package echo

import (
	"fmt"
	"math/rand"
	"net/http"
	"regexp"
	"strings"
	"testing"
)

// reference matcher: build regex from echo route pattern
func routeRegex(route string) *regexp.Regexp {
	var sb strings.Builder
	sb.WriteString("^")
	for i := 0; i < len(route); i++ {
		switch route[i] {
		case ':':
			j := i + 1
			for j < len(route) && route[j] != '/' {
				j++
			}
			sb.WriteString("([^/]+)")
			i = j - 1
		case '*':
			sb.WriteString("(.*)")
		default:
			sb.WriteString(regexp.QuoteMeta(string(route[i])))
		}
	}
	sb.WriteString("$")
	return regexp.MustCompile(sb.String())
}

func tmpFind(t *testing.T, routes []string, method, path string) (matched string, err error) {
	defer func() {
		if rec := recover(); rec != nil {
			t.Errorf("PANIC routes=%v path=%q: %v", routes, path, rec)
		}
	}()
	e := New()
	for _, rt := range routes {
		e.router.Add(http.MethodGet, rt, handlerFunc)
	}
	c := e.NewContext(nil, nil).(*context)
	e.router.Find(method, path, c)
	err = c.handler(c)
	matched, _ = c.Get("path").(string)
	return
}

func TestTmpFuzzReference(t *testing.T) {
	segments := []string{"a", "b", "ab", "abc", "x", "", "aa"}
	routeSegs := []string{"a", "b", "ab", "abc", ":p", ":q", "*"}
	rnd := rand.New(rand.NewSource(7))
	bad := 0
	for iter := 0; iter < 40000 && bad < 25; iter++ {
		n := 1 + rnd.Intn(3)
		routes := make([]string, 0, n)
		for i := 0; i < n; i++ {
			ns := 1 + rnd.Intn(3)
			p := ""
			for j := 0; j < ns; j++ {
				seg := routeSegs[rnd.Intn(len(routeSegs))]
				if seg == "*" && j != ns-1 {
					seg = "a"
				}
				p += "/" + seg
			}
			routes = append(routes, p)
		}
		ns := 1 + rnd.Intn(4)
		p := ""
		for j := 0; j < ns; j++ {
			p += "/" + segments[rnd.Intn(len(segments))]
		}
		// reference
		refMatch := false
		for _, rt := range routes {
			if routeRegex(rt).MatchString(p) {
				refMatch = true
			}
		}
		matched, err := tmpFind(t, routes, http.MethodGet, p)
		gotMatch := err == nil
		if refMatch && !gotMatch {
			bad++
			t.Errorf("MISMATCH routes=%v path=%q refMatch=%v gotMatch=%v matched=%q err=%v", routes, p, refMatch, gotMatch, matched, err)
		}
	}
}

