func routeRegex(route string) *regexp.Regexp {
	var sb strings.Builder
	sb.WriteString("^")
	for i := 0; i < len(route); i++ {
		switch route[i] {
		case ':':
			j := i + 1
			for j < len(route) && route[j] != '/' {
				j++
			}
			sb.WriteString("([^/]+)")
			i = j - 1
		case '*':
			sb.WriteString("(.*)")
		default:
			sb.WriteString(regexp.QuoteMeta(string(route[i])))
		}
	}
	sb.WriteString("$")
	return regexp.MustCompile(sb.String())
}

type findResult struct {
	matched string
	params  map[string]string
	err     error
	panicked interface{}
}

func tmpFind(routes []string, method, path string) (res findResult) {
	defer func() {
		if rec := recover(); rec != nil {
			res.panicked = rec
		}
	}()
	e := New()
	for _, rt := range routes {
		e.router.Add(http.MethodGet, rt, handlerFunc)
	}
	c := e.NewContext(nil, nil).(*context)
	e.router.Find(method, path, c)
	res.err = c.handler(c)
	res.matched, _ = c.Get("path").(string)
	res.params = map[string]string{}
	for i, n := range c.pnames {
		if i < len(c.pvalues) {
			res.params[n] = c.pvalues[i]
		}
	}
	return
}

func TestTmpFuzzBoth(t *testing.T) {
	segments := []string{"a", "b", "ab", "abc", "x", "", "aa"}
	routeSegs := []string{"a", "b", "ab", "abc", ":p", ":q", "*"}
	rnd := rand.New(rand.NewSource(1234))
	bad := 0
	for iter := 0; iter < 200000 && bad < 30; iter++ {
		n := 1 + rnd.Intn(4)
		routes := make([]string, 0, n)
		for i := 0; i < n; i++ {
			ns := 1 + rnd.Intn(4)
			p := ""
			for j := 0; j < ns; j++ {
				seg := routeSegs[rnd.Intn(len(routeSegs))]
				if seg == "*" && j != ns-1 {
					seg = "a"
				}
				p += "/" + seg
			}
			routes = append(routes, p)
		}
		ns := 1 + rnd.Intn(5)
		p := ""
		for j := 0; j < ns; j++ {
			p += "/" + segments[rnd.Intn(len(segments))]
		}
		refMatch := false
		for _, rt := range routes {
			if routeRegex(rt).MatchString(p) {
				refMatch = true
			}
		}
		res := tmpFind(routes, http.MethodGet, p)
		if res.panicked != nil {
			bad++
			t.Errorf("PANIC routes=%v path=%q: %v", routes, p, res.panicked)
			continue
		}
		gotMatch := res.err == nil
		if refMatch != gotMatch {
			bad++
			t.Errorf("MISMATCH routes=%v path=%q refMatch=%v gotMatch=%v matched=%q err=%v", routes, p, refMatch, gotMatch, res.matched, res.err)
		}
	}
	fmt.Println("done, bad =", bad)
}
EOF
