func TestTmpParamFuzz(t *testing.T) {
	segments := []string{"a", "b", "ab", "abc", "x", "aa"}
	routeSegs := []string{"a", "b", "ab", "abc", ":p", ":q", "*"}
	rnd := rand.New(rand.NewSource(555))
	bad := 0
	for iter := 0; iter < 100000 && bad < 20; iter++ {
		n := 1 + rnd.Intn(3)
		routes := make([]string, 0, n)
		for i := 0; i < n; i++ {
			ns := 1 + rnd.Intn(3)
			p := ""
			for j := 0; j < ns; j++ {
				seg := routeSegs[rnd.Intn(len(routeSegs))]
				if seg == "*" && j != ns-1 {
					seg = "a"
				}
				p += "/" + seg
			}
			routes = append(routes, p)
		}
		ns := 1 + rnd.Intn(4)
		p := ""
		for j := 0; j < ns; j++ {
			p += "/" + segments[rnd.Intn(len(segments))]
		}
		res := tmpFind(routes, http.MethodGet, p)
		if res.panicked != nil || res.err != nil {
			continue
		}
		// find the route matching res.matched and compare params
		var re *regexp.Regexp
		var rt string
		for _, r := range routes {
			if r == res.matched {
				rt = r
				re = routeRegex(r)
			}
		}
		if re == nil {
			bad++
			t.Errorf("matched unknown route %q routes=%v path=%q", res.matched, routes, p)
			continue
		}
		m := re.FindStringSubmatch(p)
		if m == nil {
			continue // route regexp does not match (echo quirk), skip
		}
		// param names in order
		var names []string
		for i := 0; i < len(rt); i++ {
			if rt[i] == ':' {
				j := i + 1
				for j < len(rt) && rt[j] != '/' {
					j++
				}
				names = append(names, rt[i+1:j])
				i = j - 1
			} else if rt[i] == '*' {
				names = append(names, "*")
			}
		}
		for idx, name := range names {
			want := m[idx+1]
			got := res.params[name]
			if want != got {
				bad++
				t.Errorf("PARAM MISMATCH routes=%v path=%q matched=%q param %q want %q got %q all=%v", routes, p, res.matched, name, want, got, res.params)
			}
		}
	}
	fmt.Println("param fuzz done, bad =", bad)
}
