func TestTmpParamFuzz(t *testing.T) {
	segments := []string{"a", "b", "ab", "abc", "x", "aa", ""}
	routeSegs := []string{"a", "b", "ab", "abc", ":p", ":q", "*", ""}
	rnd := rand.New(rand.NewSource(555))
	bad := 0
	for iter := 0; iter < 100000 && bad < 20; iter++ {
		n := 1 + rnd.Intn(3)
		routes := make([]string, 0, n)
		for i := 0; i < n; i++ {
			ns := 1 + rnd.Intn(3)
			p := ""
			for j := 0; j < ns; j++ {
				seg := routeSegs[rnd.Intn(len(routeSegs))]
				if seg == "*" && j != ns-1 {
					seg = "a"
				}
				p += "/" + seg
			}
			routes = append(routes, p)
		}
		ns := 1 + rnd.Intn(4)
		p := ""
		for j := 0; j < ns; j++ {
			p += "/" + segments[rnd.Intn(len(segments))]
		}
		res := tmpFind(routes, http.MethodGet, p)
		if res.panicked != nil {
			bad++
			t.Errorf("PANIC routes=%v path=%q: %v", routes, p, res.panicked)
			continue
		}
		refMatch := false
		for _, rt := range routes {
			if routeRegex(rt).MatchString(p) {
				refMatch = true
			}
		}
		gotMatch := res.err == nil
		if refMatch != gotMatch {
			bad++
			t.Errorf("MATCH MISMATCH routes=%v path=%q refMatch=%v gotMatch=%v matched=%q err=%v", routes, p, refMatch, gotMatch, res.matched, res.err)
			continue
		}
		if !gotMatch {
			continue
		}
		// positional param values
		var re *regexp.Regexp
		var rt string
		for _, r := range routes {
			if r == res.matched {
				rt = r
				re = routeRegex(r)
			}
		}
		if re == nil {
			bad++
			t.Errorf("matched unknown route %q routes=%v path=%q", res.matched, routes, p)
			continue
		}
		m := re.FindStringSubmatch(p)
		if m == nil {
			continue
		}
		var vals []string
		for _, v := range m[1:] {
			vals = append(vals, v)
		}
		var got []string
		for i := range res.params {
			_ = i
		}
		got = res.pvalues
		if len(vals) != len(got) {
			bad++
			t.Errorf("PARAM COUNT routes=%v path=%q matched=%q want %v got %v", routes, p, res.matched, vals, got)
			continue
		}
		for i := range vals {
			if vals[i] != got[i] {
				bad++
				t.Errorf("PARAM VALUE routes=%v path=%q matched=%q idx=%d want %v got %v", routes, p, res.matched, i, vals, got)
				break
			}
		}
	}
	fmt.Println("param fuzz done, bad =", bad)
}
