	for i, n := range c.pnames {
		if i < len(c.pvalues) {
			res.params[n] = c.pvalues[i]
		}
	}
	res.pvalues = append([]string{}, c.pvalues[:len(c.pnames)]...)
	return
}

func TestTmpSelfFuzz(t *testing.T) {
	routeSegs := []string{"a", "b", "ab", "abc", ":p", ":q", "*", ""}
	rnd := rand.New(rand.NewSource(31337))
	bad := 0
	for iter := 0; iter < 100000 && bad < 20; iter++ {
		n := 1 + rnd.Intn(4)
		routes := make([]string, 0, n)
		for i := 0; i < n; i++ {
			ns := 1 + rnd.Intn(4)
			p := ""
			for j := 0; j < ns; j++ {
				seg := routeSegs[rnd.Intn(len(routeSegs))]
				if seg == "*" && j != ns-1 {
					seg = "a"
				}
				p += "/" + seg
			}
			routes = append(routes, p)
		}
		for _, rt := range routes {
			res := tmpFind(routes, http.MethodGet, rt)
			if res.panicked != nil {
				bad++
				t.Errorf("PANIC routes=%v request=%q: %v", routes, rt, res.panicked)
				continue
			}
			if res.err != nil || res.matched != rt {
				bad++
				t.Errorf("SELF ROUTE FAIL routes=%v request=%q matched=%q err=%v", routes, rt, res.matched, res.err)
			}
		}
	}
	fmt.Println("self fuzz done, bad =", bad)
}
EOF
