func routeRegex(route string) *regexp.Regexp {
	var sb strings.Builder
	sb.WriteString("^")
	for i := 0; i < len(route); i++ {
		switch route[i] {
		case ':':
			j := i + 1
			for j < len(route) && route[j] != '/' {
				j++
			}
			sb.WriteString("([^/]+)")
			i = j - 1
		case '*':
			sb.WriteString("(.*)")
		default:
			sb.WriteString(regexp.QuoteMeta(string(route[i])))
		}
	}
	sb.WriteString("$")
	return regexp.MustCompile(sb.String())
}

// concrete path for a route pattern
func concretize(route string, rnd *rand.Rand, words []string) string {
	var sb strings.Builder
	for i := 0; i < len(route); i++ {
		switch route[i] {
		case ':':
			j := i + 1
			for j < len(route) && route[j] != '/' {
				j++
			}
			sb.WriteString(words[rnd.Intn(len(words))])
			i = j - 1
		case '*':
			n := rnd.Intn(3)
			for k := 0; k < n; k++ {
				sb.WriteString(words[rnd.Intn(len(words))])
				if k != n-1 {
					sb.WriteString("/")
				}
			}
		default:
			sb.WriteByte(route[i])
		}
	}
	return sb.String()
}

func TestTmpSelfFuzz(t *testing.T) {
	routeSegs := []string{"a", "b", "ab", "abc", ":p", ":q", "*"}
	words := []string{"a", "b", "ab", "abc", "x", "aa"}
	rnd := rand.New(rand.NewSource(31337))
	bad := 0
	for iter := 0; iter < 100000 && bad < 20; iter++ {
		n := 1 + rnd.Intn(4)
		routes := make([]string, 0, n)
		for i := 0; i < n; i++ {
			ns := 1 + rnd.Intn(4)
			p := ""
			for j := 0; j < ns; j++ {
				seg := routeSegs[rnd.Intn(len(routeSegs))]
				if seg == "*" && j != ns-1 {
					seg = "a"
				}
				p += "/" + seg
			}
			routes = append(routes, p)
		}
		for _, rt := range routes {
			path := concretize(rt, rnd, words)
			// count reference matches
			var matchedRoutes []string
			for _, r := range routes {
				if routeRegex(r).MatchString(path) {
					matchedRoutes = append(matchedRoutes, r)
				}
			}
			if len(matchedRoutes) != 1 {
				continue // ambiguous or no match per reference; skip
			}
			res := tmpFind(routes, http.MethodGet, path)
			if res.panicked != nil {
				bad++
				t.Errorf("PANIC routes=%v request=%q: %v", routes, path, res.panicked)
				continue
			}
			if res.err != nil || res.matched != matchedRoutes[0] {
				bad++
				t.Errorf("SELF ROUTE FAIL routes=%v request=%q want=%q matched=%q err=%v", routes, path, matchedRoutes[0], res.matched, res.err)
			}
		}
	}
	fmt.Println("self fuzz done, bad =", bad)
}
