func TestDefaultBinder_bindDataToMap(t *testing.T) {
	var testCases = []struct {
		name             string
		givenData        map[string][]string
		whenBindTarget   interface{}
		expectBindTarget interface{}
	}{
		{
			name:             "ok, bind to map[string]string",
			givenData:        map[string][]string{"foo": {"bar"}},
			whenBindTarget:   &map[string]string{},
			expectBindTarget: &map[string]string{"foo": "bar"},
		},
		{
			name:             "ok, bind to map[string][]string",
			givenData:        map[string][]string{"foo": {"bar"}},
			whenBindTarget:   &map[string][]string{},
			expectBindTarget: &map[string][]string{"foo": {"bar"}},
		},
		{
			name:             "ok, bind to map[string][]string multiple values",
			givenData:        map[string][]string{"foo": {"bar", "baz"}, "qux": {"1", "2"}},
			whenBindTarget:   &map[string][]string{},
			expectBindTarget: &map[string][]string{"foo": {"bar", "baz"}, "qux": {"1", "2"}},
		},
		{
			name:             "ok, bind to map[string]interface{}",
			givenData:        map[string][]string{"foo": {"bar"}},
			whenBindTarget:   &map[string]interface{}{},
			expectBindTarget: &map[string]interface{}{"foo": []string{"bar"}},
		},
		{
			name:             "nok, unsupported map type",
			givenData:        map[string][]string{"foo": {"bar"}},
			whenBindTarget:   &map[string]int{},
			expectBindTarget: &map[string]int{},
		},
	}
	for _, tc := range testCases {
		t.Run(tc.name, func(t *testing.T) {
			b := new(DefaultBinder)
			assert.NoError(t, b.bindData(tc.whenBindTarget, tc.givenData, "query"))
			assert.Equal(t, tc.expectBindTarget, tc.whenBindTarget)
		})
	}
}

func TestZZEndToEndMap(t *testing.T) {
	e := New()
	req := httptest.NewRequest(http.MethodPost, "/?q=1&q=2", strings.NewReader("f=a&f=b&g=c"))
	req.Header.Set(HeaderContentType, MIMEApplicationForm)
	c := e.NewContext(req, httptest.NewRecorder())

	sl := map[string][]string{}
	assert.NoError(t, c.Bind(&sl))
	assert.Equal(t, map[string][]string{"q": {"1", "2"}, "f": {"a", "b"}, "g": {"c"}}, sl)

	e2 := New()
	req2 := httptest.NewRequest(http.MethodGet, "/?q=1&q=2", nil)
	c2 := e2.NewContext(req2, httptest.NewRecorder())
	s := map[string]string{}
	assert.NoError(t, c2.Bind(&s))
	assert.Equal(t, map[string]string{"q": "1"}, s)
}
