func routeRegex3(route string) *regexp.Regexp {
	var sb strings.Builder
	sb.WriteString("^")
	for i := 0; i < len(route); i++ {
		switch route[i] {
		case ':':
			j := i + 1
			for j < len(route) && route[j] != '/' {
				j++
			}
			sb.WriteString("([^/]+)")
			i = j - 1
		case '*':
			sb.WriteString("(.*)")
		default:
			sb.WriteString(regexp.QuoteMeta(string(route[i])))
		}
	}
	sb.WriteString("$")
	return regexp.MustCompile(sb.String())
}

type routeDef struct {
	method string
	path   string
}

func TestTmpStatusFuzz(t *testing.T) {
	segments := []string{"a", "b", "ab", "abc", "x", "aa"}
	routeSegs := []string{"a", "b", "ab", "abc", ":p", ":q", "*"}
	methods := []string{http.MethodGet, http.MethodPost}
	rnd := rand.New(rand.NewSource(777))
	bad := 0
	for iter := 0; iter < 30000 && bad < 20; iter++ {
		n := 1 + rnd.Intn(3)
		routes := make([]routeDef, 0, n)
		for i := 0; i < n; i++ {
			ns := 1 + rnd.Intn(3)
			p := ""
			for j := 0; j < ns; j++ {
				seg := routeSegs[rnd.Intn(len(routeSegs))]
				if seg == "*" && j != ns-1 {
					seg = "a"
				}
				p += "/" + seg
			}
			routes = append(routes, routeDef{methods[rnd.Intn(len(methods))], p})
		}
		ns := 1 + rnd.Intn(4)
		p := ""
		for j := 0; j < ns; j++ {
			p += "/" + segments[rnd.Intn(len(segments))]
		}
		reqMethod := methods[rnd.Intn(len(methods))]

		// reference
		pathMatches := false
		methodMatches := false
		for _, rd := range routes {
			if routeRegex3(rd.path).MatchString(p) {
				pathMatches = true
				if rd.method == reqMethod {
					methodMatches = true
				}
			}
		}
		wantStatus := http.StatusNotFound
		if methodMatches {
			wantStatus = http.StatusOK
		} else if pathMatches {
			wantStatus = http.StatusMethodNotAllowed
		}

		e := New()
		for _, rd := range routes {
			e.Add(rd.method, rd.path, handlerFunc)
		}
		req := httptest.NewRequest(reqMethod, p, nil)
		rec := httptest.NewRecorder()
		func() {
			defer func() {
				if r := recover(); r != nil {
					bad++
					t.Errorf("PANIC routes=%v %s %q: %v", routes, reqMethod, p, r)
				}
			}()
			e.ServeHTTP(rec, req)
		}()
		if rec.Code != wantStatus {
			bad++
			t.Errorf("STATUS routes=%v req=%s %q want=%d got=%d", routes, reqMethod, p, wantStatus, rec.Code)
		}
	}
	fmt.Println("status fuzz done, bad =", bad)
}
